type Order = { customer: string; total: number };

function totalsByCustomer(orders: readonly Order[]): Record<string, number> {
  const sums = new Map<string, number>();
  for (const { customer, total } of orders) {
    sums.set(customer, (sums.get(customer) ?? 0) + total);
  }
  return Object.fromEntries(sums); // plain object only at the JSON boundary
}

console.log(JSON.stringify(totalsByCustomer([
  { customer: 'ana', total: 5 },
  { customer: 'bo', total: 2 },
  { customer: 'ana', total: 4 },
]))); // {"ana":9,"bo":2}

