function dedupeIgnoringCase(words: readonly string[]): string[] {
  const seen = new Set<string>();
  return words.filter(word => {
    const key = word.toLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

type Grid = readonly (readonly string[])[];
type Move = readonly [row: number, col: number, mark: string];

function boardHistory(board: Grid, moves: readonly Move[]): Grid[] {
  const snapshots: Grid[] = [board];
  let current = board;
  for (const [r, c, mark] of moves) {
    const row = r >= 0 ? current[r] : undefined;
    if (row !== undefined && c >= 0 && c < row.length && row[c] === '.') {
      // Copy only the path that changes: a new outer array and a new row.
      current = current.with(r, row.with(c, mark));
    }
    snapshots.push(current);
  }
  return snapshots;
}

